from collections import defaultdict
import random
from typing import Dict, List, Union, Optional, Any

def calculate_vegetable_statistics(
    preferences: Dict[str, Union[str, List[str]]],
    seed: Optional[int] = None
) -> Dict[str, Dict[str, Any]]:
    """
    Calculate statistics for vegetables preferred by people.

    Args:
        preferences: dict mapping person -> vegetable or person -> list/tuple/set of vegetables.
        seed: optional int seed for reproducible random assignments.

    Returns:
        A dictionary with keys:
            - 'veg_to_people': dict mapping vegetable -> list of people who prefer it
            - 'veg_to_person': dict mapping vegetable -> single person (randomly chosen from those who listed it)
            - 'counts': dict mapping vegetable -> random int count between 1 and 10
            - 'percentages': dict mapping vegetable -> percentage of total counts (rounded to 2 decimals)
    """
    if seed is not None:
        random.seed(seed)

    # Build veg -> list of people
    veg_to_people: Dict[str, List[str]] = defaultdict(list)
    for person, veg_value in preferences.items():
        if isinstance(veg_value, (list, tuple, set)):
            veggies_iter = veg_value
        else:
            veggies_iter = (veg_value,)
        for veg in veggies_iter:
            veg_to_people[veg].append(person)

    # If no vegetables found, return empty structures
    if not veg_to_people:
        return {
            'veg_to_people': {},
            'veg_to_person': {},
            'counts': {},
            'percentages': {}
        }

    # Map each vegetable to one person (randomly chosen among those who prefer it)
    veg_to_person: Dict[str, str] = {
        veg: random.choice(people) for veg, people in veg_to_people.items()
