    counts: Dict[str, int] = {
        veg: random.randint(1, 10) for veg in veg_to_people.keys()
    }

    total_count = sum(counts.values())
    # Compute percentages of total counts
    percentages: Dict[str, float] = {
        veg: round((cnt / total_count) * 100, 2) for veg, cnt in counts.items()
    }

    return {
        'veg_to_people': dict(veg_to_people),
        'veg_to_person': veg_to_person,
        'counts': counts,
        'percentages': percentages
    }

