import random
from collections import defaultdict
from typing import Any, Dict, Iterable, List, Tuple

def calculate_vegetable_stats(preferences: Dict[Any, Any],
                              seed: int = None,
                              pick_random_person_for_mapping: bool = False
                              ) -> Dict[str, Dict]:
    """
    Given a dictionary mapping people -> vegetable (or iterable of vegetables),
    reverse it to map each vegetable -> list of people who prefer it,
    assign a random count (1..10) to each vegetable, and compute each
    vegetable's share (%) of the total counts.

    Parameters:
    - preferences: dict where keys are person identifiers and values are either
                   a single vegetable (str) or an iterable of vegetables.
    - seed: optional int to seed the RNG for reproducible counts.
    - pick_random_person_for_mapping: if True, the veg->person mapping will pick
                                      a random person among those who listed that veg;
                                      otherwise the first encountered person is used.

    Returns: dict with keys:
    - 'veg_to_people': dict veg -> list of people
    - 'veg_to_person': dict veg -> single person (as described)
    - 'counts': dict veg -> random int count (1..10)
    - 'percentages': dict veg -> percentage of total counts (float, rounded to 2 decimals)
    - 'total_count': total sum of counts (int)
    """
    if seed is not None:
        random.seed(seed)

    # 1) Build veg -> list of people
    veg_to_people: Dict[Any, List[Any]] = defaultdict(list)
    for person, vegs in preferences.items():
        if vegs is None:
            continue
        # Normalize single value to iterable (but treat strings as single veg)
        if isinstance(vegs, str):
            veg_items = (vegs,)
        else:
            try:
                # If it's iterable (list/tuple/set), iterate
                iter(vegs)
                veg_items = vegs
            except TypeError:
                # Fallback single value
                veg_items = (vegs,)
        for veg in veg_items:
            veg_to_people[veg].append(person)

    veg_list = list(veg_to_people.keys())

    # 2) Map each vegetable to a person (either first or random pick)
    veg_to_person: Dict[Any, Any] = {}
    for veg, people in veg_to_people.items():
        if not people:
            veg_to_person[veg] = None
        else:
            veg_to_person[veg] = (random.choice(people)
                                  if pick_random_person_for_mapping else people[0])

    # 3) Assign random counts (1..10) to each vegetable
    counts: Dict[Any, int] = {}
    for veg in veg_list:
        counts[veg] = random.randint(1, 10)

    total_count = sum(counts.values())

    # 4) Compute percentages
    percentages: Dict[Any, float] = {}
    if total_count == 0:
        for veg in veg_list:
            percentages[veg] = 0.0
    else:
        for veg, cnt in counts.items():
            percentages[veg] = round((cnt / total_count) * 100.0, 2)

    return {
        'veg_to_people': dict(veg_to_people),
        'veg_to_person': veg_to_person,
        'counts': counts,
        'percentages': percentages,
        'total_count': total_count
    }

# Example usage:
if __name__ == "__main__":
    prefs = {
        "Alice": "carrot",
        "Bob": ["potato", "carrot"],
        "Carol": "spinach",
        "Dave": ["potato"],
        "Eve": "carrot"
    }
    stats = calculate_vegetable_stats(prefs, seed=42)
    import pprint
    pprint.pprint(stats)
