    "you","you'd","you'll","you're","you've","your","yours","yourself","yourselves"
}


def most_common_words_in_json_dir(
    directory: str,
    top_n: int = 10,
    text_keys: Optional[Iterable[str]] = None,
    recursive_search: bool = False,
    lowercase: bool = True,
    min_word_length: int = 1,
    ignore_stopwords: bool = True,
    extra_stopwords: Optional[Iterable[str]] = None,
    include_numbers: bool = False,
) -> List[Tuple[str, int]]:
    """
    Read all .json files in 'directory', extract textual content from each file, and return the
    top_n most common words with their counts.

    Parameters:
    - directory: path to the directory containing JSON files.
    - top_n: number of most common words to return (default 10).
    - text_keys: if provided, only extract string values whose dict key matches any of these keys
                 (searches nested dicts/lists). If None, all string values in the JSON are used.
    - recursive_search: if True, walk directory tree recursively; otherwise only top-level files.
    - lowercase: convert words to lowercase before counting.
    - min_word_length: ignore words shorter than this length.
    - ignore_stopwords: if True, filter out common English stopwords.
    - extra_stopwords: iterable of additional words to ignore (case-insensitive if lowercase=True).
    - include_numbers: if True, treat numeric tokens as words; otherwise they are ignored.

    Returns:
    - List of (word, count) tuples sorted by descending frequency (length <= top_n).
    """

    if not os.path.isdir(directory):
        raise ValueError(f"Directory not found: {directory}")

    if top_n <= 0:
        return []

    stopwords = set(_DEFAULT_STOPWORDS) if ignore_stopwords else set()
    if extra_stopwords:
        if lowercase:
            stopwords.update(w.lower() for w in extra_stopwords)
        else:
            stopwords.update(extra_stopwords)

    # Compile regex for tokenization: words with letters and optionally apostrophes; optionally include digits
    if include_numbers:
        token_re = re.compile(r"[A-Za-z0-9']+")
    else:
        token_re = re.compile(r"[A-Za-z']+")

    def iter_json_files(dirpath: str):
        if recursive_search:
            for root, _, files in os.walk(dirpath):
                for fname in files:
                    if fname.lower().endswith(".json"):
                        yield os.path.join(root, fname)
        else:
            for fname in os.listdir(dirpath):
                if fname.lower().endswith(".json"):
                    yield os.path.join(dirpath, fname)

    def collect_strings_from_value(value, collector: List[str], keys_filter: Optional[Set[str]] = None):
        # Recursively collect string values. If keys_filter is provided, this function should be
        # called only for values whose key matched; this function then collects strings from that value.
        if isinstance(value, str):
            collector.append(value)
        elif isinstance(value, dict):
            for v in value.values():
                collect_strings_from_value(v, collector, None)
        elif isinstance(value, list) or isinstance(value, tuple):
            for item in value:
                collect_strings_from_value(item, collector, None)
        else:
            # Not a string or container: ignore
            return

    def collect_strings(obj, collector: List[str], keys_filter: Optional[Set[str]] = None):
        # Traverse obj and collect strings. If keys_filter is provided, only collect strings where
        # the dict key is in keys_filter (search nested dicts).
        if isinstance(obj, str):
            if keys_filter is None:
                collector.append(obj)
            # if keys_filter is not None and we're here, it means this str is part of a list/positional
            # value; only collected when its parent key matched, which is handled elsewhere.
            return
        elif isinstance(obj, dict):
            for k, v in obj.items():
                if keys_filter is not None and k in keys_filter:
                    collect_strings_from_value(v, collector, None)
                else:
                    collect_strings(v, collector, keys_filter)
        elif isinstance(obj, list) or isinstance(obj, tuple):
            for item in obj:
                collect_strings(item, collector, keys_filter)
        else:
            return

    word_counter: Counter = Counter()

    for filepath in iter_json_files(directory):
        try:
            with open(filepath, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            # Skip files that can't be read / aren't valid JSON
            continue

        strings: List[str] = []
        keys_filter = set(text_keys) if text_keys is not None else None
        collect_strings(data, strings, keys_filter)

        for text in strings:
            if lowercase:
                text_proc = text.lower()
            else:
                text_proc = text
            tokens = token_re.findall(text_proc)
            for tok in tokens:
                if lowercase:
                    tok_key = tok.lower()
                else:
                    tok_key = tok
                if len(tok_key) < min_word_length:
                    continue
                if tok_key in stopwords:
                    continue
                word_counter[tok_key] += 1

    return word_counter.most_common(top_n)


# Example usage:
# top_words = most_common_words_in_json_dir("path/to/json_dir", top_n=20, text_keys=["text","content"])
# print(top_words)

def analyze_degree_fft(items, key=None):
    """
    Sort items ascending by their "degree" value, then compute mean, median, and mode for:
      1) the sorted degree values
      2) the (rounded-to-nearest-integer) magnitudes of the FFT of the degree values

    Parameters:
      items : list
        - A list of numbers, or a list of dicts/objects. If items are numeric, they are treated as degree values.
      key : None | str | callable
        - If None:
            * numeric items are used directly
            * for dict-like items, the function will look for 'degree' or 'deg' keys or an attribute 'degree'
        - If str: used as a key for dicts or attribute name for objects (e.g. 'degree')
        - If callable: called as key(item) to obtain the degree value

    Returns:
      dict with keys:
        'sorted_items' : list
          The original items sorted in ascending order by degree value (items themselves, not degree list).
        'degree_values' : list of floats
          The sorted degree values.
        'degree_stats' : dict with keys 'mean', 'median', 'mode'
        'fft_magnitudes_rounded' : list of ints
          Absolute values of FFT of degree values, rounded to nearest integer.
        'fft_stats' : dict with keys 'mean', 'median', 'mode'

    Notes:
      - Mode is returned as a single value; if multiple values tie for most frequent, the smallest one is returned.
      - Requires numpy (a free library). Uses Python's standard statistics and collections modules.
    """
    import numpy as np
    import statistics
    from collections import Counter

    if not isinstance(items, list):
        raise TypeError("items must be a list")

    if len(items) == 0:
        raise ValueError("items list must not be empty")

    # helper to extract degree value
    def _extract(item):
        if callable(key):
            return float(key(item))
        if key is not None and isinstance(key, str):
            # dict-like
            if isinstance(item, dict):
                if key in item:
                    return float(item[key])
                else:
                    raise KeyError(f"Key '{key}' not found in item {item}")
            # object attribute
            if hasattr(item, key):
                return float(getattr(item, key))
            # fallthrough
            raise KeyError(f"Attribute/key '{key}' not found on item {item}")
        # default behavior
        # numeric item
        if isinstance(item, (int, float, np.number)):
            return float(item)
        # dict-like common keys
        if isinstance(item, dict):
            if 'degree' in item:
                return float(item['degree'])
            if 'deg' in item:
                return float(item['deg'])
            raise KeyError(f"No 'degree'/'deg' key found in dict item {item}")
        # object attribute fallback
        if hasattr(item, 'degree'):
            return float(getattr(item, 'degree'))
        if hasattr(item, 'deg'):
            return float(getattr(item, 'deg'))
        raise TypeError(f"Cannot extract degree from item: {item!r}; provide a 'key' parameter")

    # extract degrees paired with items
    paired = []
    for it in items:
        try:
            deg = _extract(it)
        except Exception as e:
            raise type(e)(f"Error extracting degree from item {it!r}: {e}") from e
        paired.append((deg, it))

    # sort by degree ascending
    paired.sort(key=lambda x: x[0])
    degree_values = [float(d) for d, _ in paired]
    sorted_items = [it for _, it in paired]

    # statistics helpers
    def _mean(seq):
        return float(statistics.mean(seq)) if len(seq) > 0 else float('nan')

    def _median(seq):
        return float(statistics.median(seq)) if len(seq) > 0 else float('nan')

    def _mode(seq):
        if len(seq) == 0:
            return None
        cnt = Counter(seq)
        most_common_count = max(cnt.values())
        candidates = [val for val, c in cnt.items() if c == most_common_count]
        # choose the smallest candidate to make deterministic
        return min(candidates)

    degree_stats = {
        'mean': _mean(degree_values),
        'median': _median(degree_values),
        'mode': _mode(degree_values)
    }

    # FFT magnitude, then round to nearest integer
    arr = np.asarray(degree_values, dtype=float)
    # If single value, FFT still returns one value equal to that value
    fft_vals = np.fft.fft(arr)
    magnitudes = np.abs(fft_vals)
    # round to nearest integer (numpy.rint) then convert to Python ints
    magnitudes_rounded = np.rint(magnitudes).astype(int).tolist()

    # compute stats on rounded magnitudes (convert to Python numbers)
    fft_stats = {
        'mean': float(statistics.mean(magnitudes_rounded)),
        'median': float(statistics.median(magnitudes_rounded)),
        'mode': _mode(magnitudes_rounded)
    }

    return {
        'sorted_items': sorted_items,
        'degree_values': degree_values,
        'degree_stats': degree_stats,
        'fft_magnitudes_rounded': magnitudes_rounded,
        'fft_stats': fft_stats
    }

# Example usage:
# items = [{'name':'a','degree':3}, {'name':'b','degree':1}, {'name':'c','degree':2}]
