```python
import os
import re
import nltk
from nltk.corpus import stopwords

def count_unique_non_stop_words(dir_path: str, recursive: bool = False) -> int:
    """
    Count the number of unique non-stop words across all '.txt' files in dir_path.

    - Uses NLTK's English stopwords (will auto-download the 'stopwords' resource if missing).
    - Tokenization: matches alphabetic words only (no digits or underscores).
    - Case-insensitive (counts 'Apple' and 'apple' as the same word).
    - If recursive=True, will include .txt files in subdirectories.

    Args:
        dir_path: Path to the directory containing .txt files.
        recursive: Whether to search subdirectories recursively.

    Returns:
        The count of unique non-stop words (int).

    Raises:
        ValueError: if dir_path is not an existing directory.
    """
