Here's a single self-contained Python function that uses the free NLTK library to count unique non-stop words across all ".txt" files in a given directory. It will automatically download the NLTK stopwords data if not already present. It ignores numbers and punctuation, lowercases text, and by default only checks files directly in the provided directory (you can enable recursion).

Usage example:
count = count_unique_non_stop_words("/path/to/folder")
print(count)

Function:

```python
def count_unique_non_stop_words(directory, language='english', recursive=False):
    """
    Count unique non-stop words across all '.txt' files in the given directory.

    Parameters:
    - directory (str): path to the directory containing .txt files
    - language (str): stopword language to use (default 'english')
    - recursive (bool): if True, search subdirectories recursively (default False)

    Returns:
    - int: number of unique non-stop words found across all .txt files

    Notes:
    - Uses NLTK stopwords (will attempt to download them if missing).
    - Only alphabetic words are considered (numbers and punctuation are ignored).
    """
    import os
    import re

    try:
        import nltk
        from nltk.corpus import stopwords
    except Exception as e:
        raise ImportError("NLTK is required. Install with `pip install nltk`. Error: " + str(e))

    # Ensure stopwords corpus is available
    try:
        stopset = set(stopwords.words(language))
    except LookupError:
        # Try to download stopwords data and retry
        nltk.download('stopwords', quiet=True)
        try:
            stopset = set(stopwords.words(language))
        except Exception as e:
            raise RuntimeError(f"Could not load stopwords for language='{language}': {e}")

    if not os.path.isdir(directory):
        raise ValueError(f"Directory not found: {directory}")

    unique_words = set()
    # regex: match sequences of letters (Unicode-aware). This avoids numbers and underscores.
    token_re = re.compile(r"\b[^\W\d_]+\b", flags=re.UNICODE)

    def process_file(path):
        try:
            with open(path, 'r', encoding='utf-8') as f:
                text = f.read()
        except UnicodeDecodeError:
            # fallback encoding
            with open(path, 'r', encoding='latin-1') as f:
                text = f.read()
        tokens = token_re.findall(text.lower())
        for t in tokens:
            if t not in stopset:
                unique_words.add(t)

    if recursive:
        for root, _, files in os.walk(directory):
            for fname in files:
                if fname.lower().endswith('.txt'):
                    process_file(os.path.join(root, fname))
    else:
        for fname in os.listdir(directory):
            if fname.lower().endswith('.txt'):
                path = os.path.join(directory, fname)
                if os.path.isfile(path):
                    process_file(path)

    return len(unique_words)
