    except ImportError:
        raise ImportError("ZoneInfo not available. Use Python 3.9+ or install backports.zoneinfo")

def convert_timezone(dt, from_tz=None, to_tz="UTC", fmt=None):
    """
    Convert a datetime from one timezone to another.

    Parameters:
    - dt: datetime.datetime instance, ISO-8601 string, or Unix timestamp (int/float).
          If dt is an ISO string with explicit timezone information, from_tz is ignored.
    - from_tz: source timezone as IANA name string (e.g., "America/New_York"). Required if dt is naive.
    - to_tz: target timezone as IANA name string (default "UTC").
    - fmt: optional strftime format. If provided, the function returns a formatted string;
           otherwise it returns a timezone-aware datetime object.

    Returns:
    - datetime with tzinfo set to the target timezone, or a formatted string if fmt is given.

    Examples:
    - convert_timezone("2023-08-27T15:00:00", "America/New_York", "Europe/London")
    - convert_timezone(datetime.utcnow(), "UTC", "Asia/Tokyo", "%Y-%m-%d %H:%M:%S %Z%z")
    - convert_timezone(1693148400, "UTC", "America/Los_Angeles")
    """
    # Parse input if string
    if isinstance(dt, str):
        s = dt.strip()
        # Accept 'Z' for UTC
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt_obj = datetime.fromisoformat(s)
        except ValueError:
            # fallback: try a common datetime format
            try:
                dt_obj = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
            except ValueError:
                raise ValueError("String datetime not in ISO format and fallback parsing failed.")
    elif isinstance(dt, (int, float)):
        # treat as Unix timestamp (seconds)
        if from_tz is None:
            # default timestamp to UTC if not specified
            from_zone = ZoneInfo("UTC")
        else:
            try:
                from_zone = ZoneInfo(from_tz)
            except ZoneInfoNotFoundError:
                raise ValueError(f"Unknown source timezone: {from_tz}")
        dt_obj = datetime.fromtimestamp(dt, tz=from_zone)
    elif isinstance(dt, datetime):
        dt_obj = dt
    else:
        raise TypeError("dt must be a datetime, ISO-8601 string, or Unix timestamp (int/float).")

    # If parsed string/datetime already has tzinfo, ignore from_tz
    if dt_obj.tzinfo is None:
        if from_tz is None:
            raise ValueError("Input datetime is naive; from_tz must be provided.")
        try:
            src_zone = ZoneInfo(from_tz)
        except ZoneInfoNotFoundError:
            raise ValueError(f"Unknown source timezone: {from_tz}")
        # Attach source timezone (treat the naive time as wall time in from_tz)
        dt_obj = dt_obj.replace(tzinfo=src_zone)

    # Convert to target timezone
    try:
        dst_zone = ZoneInfo(to_tz)
    except ZoneInfoNotFoundError:
        raise ValueError(f"Unknown target timezone: {to_tz}")

    converted = dt_obj.astimezone(dst_zone)

    if fmt:
        return converted.strftime(fmt)
    return converted

