def export_function_specs_to_csv(f_list, file_path):
    """
    Exports specifications of functions in `f_list` to a CSV file at `file_path`.
    CSV columns:
      - 'Function Name': The name of the function.
      - 'Number of Arguments': The number of arguments the function takes (count of signature parameters).
      - 'Defaults': Default values for the function's arguments, if any (repr of defaults, joined by '; ').
      - 'Annotations': Type annotations of the function's arguments and return value, if any
                     (shown as 'param:annotation', joined by '; ', return as 'return:annotation').
      - 'Is Lambda': Boolean indicating whether the function is a lambda.

    f_list: iterable of callables (functions, lambdas, callables with __call__, etc.)
    file_path: path to write the CSV file (will be overwritten).
    """
    import inspect
    import csv

    def _format_annotation(a):
        # Return a readable string for an annotation
        if a is inspect._empty:
            return ''
        try:
            # For types, try to use their qualified name; otherwise fallback to repr
            if isinstance(a, type):
                return a.__module__ + "." + a.__qualname__ if getattr(a, "__module__", None) not in ("builtins", None) else a.__qualname__
            return repr(a)
        except Exception:
            return str(a)

    def _format_default(d):
        if d is inspect._empty:
            return ''
        try:
            return repr(d)
        except Exception:
            return str(d)

    fieldnames = ['Function Name', 'Number of Arguments', 'Defaults', 'Annotations', 'Is Lambda']
    with open(file_path, 'w', newline='', encoding='utf-8') as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()

        for f in f_list:
            row = {
                'Function Name': getattr(f, "__name__", type(f).__name__),
                'Number of Arguments': '',
                'Defaults': '',
                'Annotations': '',
                'Is Lambda': False,
            }

            try:
                sig = inspect.signature(f)
                params = sig.parameters

                # Number of arguments: count of parameters in signature
                row['Number of Arguments'] = len(params)

                # Defaults: collect parameters that have defaults
                defaults_items = []
                for name, param in params.items():
                    if param.default is not inspect._empty:
                        defaults_items.append(f"{name}={_format_default(param.default)}")
                row['Defaults'] = '; '.join(defaults_items)

                # Annotations: param:annotation and return
                ann_items = []
                for name, param in params.items():
                    if param.annotation is not inspect._empty:
                        ann_items.append(f"{name}:{_format_annotation(param.annotation)}")
                if sig.return_annotation is not inspect._empty:
                    ann_items.append(f"return:{_format_annotation(sig.return_annotation)}")
                row['Annotations'] = '; '.join(ann_items)

                # Is lambda: function and name is "<lambda>"
                row['Is Lambda'] = (inspect.isfunction(f) and getattr(f, "__name__", "") == "<lambda>")

            except (ValueError, TypeError):
                # Some callables (builtins, C functions, etc.) may not have inspectable signatures.
                # Leave the signature-related fields empty or set to reasonable defaults.
                row['Number of Arguments'] = ''
                row['Defaults'] = ''
                row['Annotations'] = ''
                # Try a best-effort lambda detection by name
                row['Is Lambda'] = getattr(f, "__name__", "") == "<lambda>"

            writer.writerow(row)

