import inspect
import csv
from typing import Iterable, Callable, Any


def export_function_specs_to_csv(f_list: Iterable[Callable[..., Any]], file_path: str) -> None:
    """
    Exports specifications of functions in f_list to a CSV file at file_path.
    CSV columns:
      - 'Function Name': The name of the function.
      - 'Number of Arguments': The number of arguments the function takes (number of declared parameters).
      - 'Defaults': Default values for the function's arguments, if any (formatted as "arg=repr(value), ...").
      - 'Annotations': Type annotations of the function's arguments and return value, if any
                       (formatted as "arg:annotation, return:annotation").
      - 'Is Lambda': Boolean indicating whether the function is a lambda (True/False).

    f_list: iterable of callables (functions). Non-callables are ignored.
    file_path: path to write the CSV file. Existing file will be overwritten.
    """
    headers = ['Function Name', 'Number of Arguments', 'Defaults', 'Annotations', 'Is Lambda']
    rows = []

    def _ann_to_str(a):
        # Try to produce a readable annotation string
        try:
            # For types, show the type name if possible
            if hasattr(a, '__name__'):
                return a.__name__
            # For typing objects, repr is often informative
            return repr(a)
        except Exception:
            return str(a)

    for item in f_list:
        if not callable(item):
            # Skip non-callables (could instead write a row marking as invalid)
            continue

        name = getattr(item, '__name__', type(item).__name__)
        is_lambda = inspect.isfunction(item) and name == "<lambda>"

        defaults_str = ""
        annotations_str = ""
        num_args = ""

        try:
            sig = inspect.signature(item)
            params = sig.parameters
            num_args = len(params)

            # Defaults
            defaults = {}
            for pname, param in params.items():
                if param.default is not inspect._empty:
                    defaults[pname] = param.default
            if defaults:
                defaults_str = ", ".join(f"{k}={repr(v)}" for k, v in defaults.items())

            # Annotations: parameters + return (if present)
            annotations = {}
            for pname, param in params.items():
                if param.annotation is not inspect._empty:
                    annotations[pname] = param.annotation
            if sig.return_annotation is not inspect._empty:
                annotations['return'] = sig.return_annotation
            if annotations:
                annotations_str = ", ".join(f"{k}: {_ann_to_str(v)}" for k, v in annotations.items())

        except (ValueError, TypeError):
            # Some callables (builtins, C functions, certain callables) may not have a signature.
            # Try getfullargspec where possible (works for Python functions).
            try:
                fas = inspect.getfullargspec(item)
                args = fas.args or []
                num_args = len(args)
                defaults = {}
                if fas.defaults:
                    # defaults correspond to the last N args
                    ndef = len(fas.defaults)
                    for arg_name, def_val in zip(args[-ndef:], fas.defaults):
                        defaults[arg_name] = def_val
                if defaults:
                    defaults_str = ", ".join(f"{k}={repr(v)}" for k, v in defaults.items())
                if fas.annotations:
                    annotations = {k: v for k, v in fas.annotations.items()}
                    if annotations:
                        annotations_str = ", ".join(f"{k}: {_ann_to_str(v)}" for k, v in annotations.items())
            except Exception:
                # Give up and leave fields empty or as best-effort
                pass

        rows.append([name, num_args, defaults_str, annotations_str, bool(is_lambda)])

    # Write CSV
    with open(file_path, mode='w', newline='', encoding='utf-8') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(headers)
        writer.writerows(rows)

