Here's a self-contained Python function that uses NLTK (a free library). It tokenizes the sentence, removes the last "word" token (skipping trailing punctuation), POS-tags the remaining tokens, and returns a dictionary counting each POS tag.

```python
def count_pos_without_last_word(sentence):
    """
    Count POS tags in the given sentence excluding the last word (ignoring trailing punctuation).
    Uses NLTK for tokenization and POS tagging.

    Returns a dict mapping POS tag -> count.
    """
    import re
    try:
        import nltk
    except Exception as e:
        raise RuntimeError("NLTK is required. Install with `pip install nltk`.") from e

    # Ensure required NLTK resources are available
    try:
        nltk.data.find('tokenizers/punkt')
    except LookupError:
        nltk.download('punkt', quiet=True)
    try:
        nltk.data.find('taggers/averaged_perceptron_tagger')
    except LookupError:
        nltk.download('averaged_perceptron_tagger', quiet=True)

    # Handle empty input
    if not sentence or not isinstance(sentence, str):
        return {}

    tokens = nltk.word_tokenize(sentence)

    # Find index of the last token that contains at least one alphanumeric character (a "word")
    last_word_idx = None
    for i in range(len(tokens) - 1, -1, -1):
        if re.search(r'\w', tokens[i]):
            last_word_idx = i
            break

    # If there is no word token, nothing to remove -> return empty counts
    if last_word_idx is None:
        return {}

    # Remove that last word token
    tokens_without_last_word = tokens[:last_word_idx] + tokens[last_word_idx + 1:]

    # If nothing left, return empty dict
    if not tokens_without_last_word:
        return {}

    # POS tag and count
    tagged = nltk.pos_tag(tokens_without_last_word)
    counts = {}
    for _, tag in tagged:
        counts[tag] = counts.get(tag, 0) + 1

    return counts

