Here's a self-contained Python function that flattens an arbitrarily nested list/iterable of numeric values and computes the interquartile range (IQR = Q3 - Q1) using NumPy (a free library). It converts values to float and ignores NaNs; it raises an error if no numeric values are found or a non-numeric element cannot be converted.

```python
def iqr_nested(L):
    """
    Compute the interquartile range (IQR = Q3 - Q1) of all numeric elements
    in a nested list/iterable L. Uses NumPy.

    Args:
        L: nested list/tuple/set/iterable containing numeric values (arbitrary depth)

    Returns:
        float: IQR (Q3 - Q1)

    Raises:
        ValueError: if no numeric elements are found
        TypeError: if a non-numeric element cannot be converted to float
    """
    import numpy as np
    from collections.abc import Iterable

    def is_non_string_iterable(x):
        return isinstance(x, Iterable) and not isinstance(x, (str, bytes, bytearray))

    def _flatten(obj):
        if is_non_string_iterable(obj):
            for item in obj:
                yield from _flatten(item)
        else:
            yield obj

    flat = list(_flatten(L))
    nums = []
    for x in flat:
        try:
            v = float(x)
        except Exception:
            raise TypeError(f"Non-numeric element encountered and not convertible to float: {x!r}")
        if not np.isnan(v):
            nums.append(v)

    if len(nums) == 0:
        raise ValueError("No numeric elements found to compute IQR.")

    q1, q3 = np.percentile(nums, [25, 75])
    return float(q3 - q1)
