def count_xyz_values(d: List[Dict[str, Any]]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values for keys "x", "y", and "z" in a list of dictionaries.

    Parameters:
      d: list of dicts

    Returns:
      A dict mapping each of 'x', 'y', 'z' to a dict of value -> count.
      Missing keys in an item are ignored. Values are used as-is (must be hashable).
    """
    counters = {k: Counter() for k in ('x', 'y', 'z')}
    for item in d:
        if not isinstance(item, dict):
            continue
        for k in counters:
            if k in item:
                counters[k][item[k]] += 1
    # convert Counters to normal dicts for nicer JSON-serializable output
    return {k: dict(counters[k]) for k in counters}

# Example:
if __name__ == "__main__":
    d = [
        {"x": 1, "y": "a"},
        {"x": 1, "y": "b", "z": 3},
        {"x": 2, "z": 3},
        {"y": "a"},
        {"x": 1, "z": 4}
    ]
    print(count_xyz_values(d))
    # Output:
    # {'x': {1: 3, 2: 1}, 'y': {'a': 2, 'b': 1}, 'z': {3: 2, 4: 1}}
