Here's a single self-contained Python function that extracts numeric values from a JSON-like structure (nested dicts/lists) following a specified key path (supports wildcard '*' to iterate all keys/elements) and visualizes the extracted numbers using matplotlib. The code includes reasonable error handling and options to choose the plot type, bins, save the figure, etc.

Copy-paste and run this in any environment that has matplotlib installed (it's free).


```python
import json
import numbers
from typing import Any, List, Union, Sequence
import matplotlib.pyplot as plt

def extract_and_visualize_json(
    json_obj: Any,
    path: Union[str, Sequence[str]],
    plot_type: str = "hist",
    bins: int = 30,
    title: str = None,
    xlabel: str = None,
    ylabel: str = None,
    show: bool = True,
    save_path: str = None,
    convert_strings: bool = True,
) -> List[float]:
    """
    Extract numeric values from a JSON-like object following a path of keys and visualize them.

    Parameters:
    - json_obj: Parsed JSON (dict/list/primitive).
    - path: Path describing how to reach numeric values.
        - Can be a list/tuple of keys, e.g. ['items', '*', 'value']
        - Or a dotted string, e.g. "items.*.value"
        - Use '*' to mean "all keys/elements at this level" (wildcard).
    - plot_type: 'hist' (default), 'line', or 'box'.
    - bins: Number of bins for histogram.
    - title/xlabel/ylabel: Strings for plot labeling. Reasonable defaults are used if None.
    - show: If True, display the plot with plt.show().
    - save_path: If provided, save the figure to this file path (png/pdf/...).
    - convert_strings: If True, attempt to coerce numeric strings to floats.

    Returns:
    - List of extracted numeric values (floats or ints).

    Raises:
    - ValueError if no numeric values were found or plot_type unknown.
    """

    # Normalize path to list of tokens
    if isinstance(path, str):
        path_tokens = [p for p in path.split('.') if p != ""]
    else:
        path_tokens = list(path)

    results: List[float] = []

    def is_numeric(x):
        return isinstance(x, numbers.Number) and not isinstance(x, bool)

    def try_convert(x):
        if is_numeric(x):
            return x
        if convert_strings and isinstance(x, str):
            try:
                # allow ints and floats in strings
                if '.' in x or 'e' in x.lower():
                    return float(x)
                else:
                    return int(x)
            except Exception:
                return None
        return None

    def collect_leaf(obj):
        # collect numeric values from obj (handles list/dict/primitive)
        if is_numeric(obj):
            results.append(obj)
        elif isinstance(obj, str) and convert_strings:
            val = try_convert(obj)
            if val is not None:
                results.append(val)
        elif isinstance(obj, list):
            for el in obj:
                if is_numeric(el):
                    results.append(el)
                elif isinstance(el, str) and convert_strings:
                    val = try_convert(el)
                    if val is not None:
                        results.append(val)
        elif isinstance(obj, dict):
            for v in obj.values():
                if is_numeric(v):
                    results.append(v)
                elif isinstance(v, str) and convert_strings:
                    val = try_convert(v)
                    if val is not None:
                        results.append(val)
        # otherwise nothing to collect

    def traverse(obj, idx):
        if idx >= len(path_tokens):
            collect_leaf(obj)
            return

        key = path_tokens[idx]

        # wildcard: iterate through all child elements (values for dicts, elements for lists)
        if key == "*":
            if isinstance(obj, dict):
                for v in obj.values():
                    traverse(v, idx + 1)
            elif isinstance(obj, list):
                for el in obj:
                    traverse(el, idx + 1)
            else:
                # nothing to iterate
                return
        else:
            # normal key: if dict, use key; if list, try numeric index
            if isinstance(obj, dict):
                if key in obj:
                    traverse(obj[key], idx + 1)
                else:
                    # key missing -> nothing
                    return
            elif isinstance(obj, list):
                # try integer indexing
                try:
                    i = int(key)
                except Exception:
                    # not an index -> nothing
                    return
                if 0 <= i < len(obj):
                    traverse(obj[i], idx + 1)
                else:
                    return
            else:
                # reached a primitive but still tokens remain -> nothing
                return

    # run extraction
    traverse(json_obj, 0)

    if len(results) == 0:
        raise ValueError(f"No numeric values found for path {'.'.join(path_tokens)}")

    # convert results to floats for plotting when needed
    numeric_values = [float(x) for x in results]

    # Plotting
    plt.figure(figsize=(8, 5))
    pt = plot_type.lower()
    if pt == "hist":
        plt.hist(numeric_values, bins=bins, edgecolor="black")
        if title is None:
            title = f"Histogram of values at path {'.'.join(path_tokens)}"
        if xlabel is None:
            xlabel = "Value"
        if ylabel is None:
            ylabel = "Count"
    elif pt == "line":
        plt.plot(numeric_values, marker='o', linestyle='-')
        if title is None:
            title = f"Sequence of values at path {'.'.join(path_tokens)}"
        if xlabel is None:
            xlabel = "Index"
        if ylabel is None:
            ylabel = "Value"
    elif pt == "box":
        plt.boxplot(numeric_values, vert=True)
        if title is None:
            title = f"Boxplot of values at path {'.'.join(path_tokens)}"
        if xlabel is None:
            xlabel = ""
        if ylabel is None:
            ylabel = "Value"
    else:
        raise ValueError(f"Unknown plot_type '{plot_type}'. Use 'hist', 'line', or 'box'.")

    plt.title(title)
    if xlabel:
        plt.xlabel(xlabel)
    if ylabel:
        plt.ylabel(ylabel)
    plt.tight_layout()

    if save_path:
        plt.savefig(save_path, dpi=150)

    if show:
        plt.show()
    else:
        plt.close()

    return results

# Example usage:
if __name__ == "__main__":
    sample_json = {
        "items": [
            {"id": 1, "value": "10.5"},
            {"id": 2, "value": 7},
            {"id": 3, "value": 12.1},
            {"id": 4, "value": "bad"},  # non-numeric string will be ignored
        ],
        "meta": {"count": 4}
    }

    # Extract all item.value entries and show histogram
    vals = extract_and_visualize_json(sample_json, "items.*.value", plot_type="hist", bins=5)
    print("Extracted values:", vals)
```

Notes:
- Use '*' in the path where you want to iterate through all entries (e.g., "root.*.score").
- If a middle token is a list index, you may provide a numeric token like "items.0.value".
- The function tries to coerce numeric strings to numbers (configurable with convert_strings).
- Returns the list of extracted numeric values so you can further process them.

Here's a single self-contained Python function that extracts numeric values from a nested JSON-like Python structure (dicts/lists) following a specified path and then visualizes the extracted numbers. It uses free libraries only (numpy and matplotlib). The function is flexible: the path can be a list of keys or a dot-separated string, supports wildcards ("*") to iterate lists/dicts, allows integer indices for lists, and can cast numeric strings to numbers.

Copy-paste this into a .py file and run.

```python
import json
from typing import Any, List, Union, Tuple, Optional
import numbers
import numpy as np
import matplotlib.pyplot as plt

def extract_and_visualize(
    json_obj: Any,
    path: Union[str, List[Union[str, int]]],
    plot_type: str = "hist",
    bins: int = 30,
    title: Optional[str] = None,
    xlabel: Optional[str] = None,
    ylabel: Optional[str] = None,
    figsize: Tuple[int, int] = (8, 5),
    save_path: Optional[str] = None,
    show: bool = True,
    numeric_cast: bool = True,
    sort_values: bool = False
) -> Tuple[np.ndarray, plt.Figure, plt.Axes]:
    """
    Extract numeric values from a nested JSON-like structure following 'path'
    and visualize them.

    Parameters:
    - json_obj: nested dict/list structure (already parsed JSON or equivalent).
    - path: list of keys/indices or dot-separated string describing the path.
            Use "*" to mean "all elements" at this level (works for lists and dicts).
            Example paths:
              - "data.items.*.value"
              - ["data", "items", "*", "value"]
              - "top.level.0.score"  (0 is a list index)
    - plot_type: one of 'hist', 'line', 'bar', 'box'. Defaults to 'hist'.
    - bins: bins for histogram (if plot_type == 'hist').
    - title, xlabel, ylabel: plot labels (auto-generated if None).
    - figsize: size of the matplotlib figure.
    - save_path: if provided, save plot to this path (png/pdf/etc).
    - show: if True, call plt.show() before returning (set False for headless use).
    - numeric_cast: if True, attempt to convert numeric-looking strings (e.g. "3.14") to numbers.
    - sort_values: if True, sort extracted numeric values before plotting (affects line/hist order).

    Returns:
    - (values_array, fig, ax) where values_array is a numpy array of extracted numbers.

    Raises:
    - ValueError if no numeric values are found.
    """

    # Helper -> normalize path
    if isinstance(path, str):
        # split on '.' but keep numeric keys like "0"
        path_parts = path.split(".") if path else []
    else:
        path_parts = list(path)

    def _is_number(x: Any) -> bool:
        return isinstance(x, numbers.Number) and not isinstance(x, bool)

    def _maybe_cast_number(x: Any):
        if _is_number(x):
            return x
        if numeric_cast and isinstance(x, str):
            try:
                # try int first, then float
                if x.isdigit() or (x.startswith("-") and x[1:].isdigit()):
                    return int(x)
                return float(x)
            except Exception:
                return None
        return None

    # Recursive traversal to collect numbers
    collected: List[float] = []

    def traverse(node: Any, parts: List[Union[str, int]], idx: int = 0):
        if idx >= len(parts):
            # reached end of path -> collect numbers from node
            if _is_number(node):
                collected.append(float(node))
                return
            if isinstance(node, str) and numeric_cast:
                casted = _maybe_cast_number(node)
                if casted is not None:
                    collected.append(float(casted))
                    return
            if isinstance(node, list):
                for el in node:
                    if _is_number(el):
                        collected.append(float(el))
                    elif isinstance(el, str) and numeric_cast:
                        casted = _maybe_cast_number(el)
                        if casted is not None:
                            collected.append(float(casted))
            elif isinstance(node, dict):
                # flatten dict values and try to collect numbers
                for v in node.values():
                    if _is_number(v):
                        collected.append(float(v))
                    elif isinstance(v, str) and numeric_cast:
                        casted = _maybe_cast_number(v)
                        if casted is not None:
                            collected.append(float(casted))
            return

        comp = parts[idx]

        # wildcard: iterate over elements/values
        if comp == "*" or comp == slice(None):
            if isinstance(node, list):
                for el in node:
                    traverse(el, parts, idx + 1)
            elif isinstance(node, dict):
                for v in node.values():
                    traverse(v, parts, idx + 1)
            else:
                # nothing to iterate
                return
            return

        # if comp is an integer index (or looks like one)
        if isinstance(comp, int) or (isinstance(comp, str) and comp.isdigit()):
            try:
                index = int(comp)
                if isinstance(node, list):
                    if 0 <= index < len(node):
                        traverse(node[index], parts, idx + 1)
                else:
                    # trying to index a non-list -> nothing
                    return
            except Exception:
                return
            return

        # normal dict key access
        if isinstance(node, dict):
            if comp in node:
                traverse(node[comp], parts, idx + 1)
            else:
                # key missing -> nothing
                return
            return

        # cannot proceed if node is not indexable by key
        return

    traverse(json_obj, path_parts, 0)

    arr = np.array(collected, dtype=float)
    if arr.size == 0:
        raise ValueError(f"No numeric values found for path {path_parts!r}")

    if sort_values:
        arr = np.sort(arr)

    # Prepare plot
    fig, ax = plt.subplots(figsize=figsize)
    if plot_type == "hist":
        ax.hist(arr, bins=bins, color="#4c72b0", edgecolor="k")
        ax.set_ylabel(ylabel or "Frequency")
        ax.set_xlabel(xlabel or "Value")
    elif plot_type == "line":
        ax.plot(np.arange(len(arr)), arr, marker="o", linestyle="-", color="#4c72b0")
        ax.set_xlabel(xlabel or "Index")
        ax.set_ylabel(ylabel or "Value")
    elif plot_type == "bar":
        ax.bar(np.arange(len(arr)), arr, color="#4c72b0")
        ax.set_xlabel(xlabel or "Index")
        ax.set_ylabel(ylabel or "Value")
    elif plot_type == "box":
        ax.boxplot(arr, vert=True)
        ax.set_xlabel(xlabel or "")
        ax.set_ylabel(ylabel or "Value")
    else:
        plt.close(fig)
        raise ValueError(f"Unsupported plot_type: {plot_type!r}. Choose 'hist','line','bar','box'.")

    ax.set_title(title or f"{plot_type.capitalize()} of values at path: {'.'.join(map(str,path_parts))}")
    ax.grid(True, linestyle="--", alpha=0.3)

    if save_path:
        fig.savefig(save_path, bbox_inches="tight")

    if show:
        plt.show()

    return arr, fig, ax


# Example usage:
if __name__ == "__main__":
    # example JSON-like data
    example = {
        "data": {
            "items": [
                {"id": 1, "value": "3.2"},
                {"id": 2, "value": 4.5},
                {"id": 3, "value": "7"},
                {"id": 4, "value": None},
            ],
            "meta": {"count": 4}
        },
        "other": [10, 20, {"value": 5}]
    }

    # Extract numbers from data.items.*.value and show histogram
    vals, fig, ax = extract_and_visualize(example, "data.items.*.value", plot_type="hist", bins=5)
    print("Extracted values:", vals)

    # Extract numbers from other.* (wildcard) and show line plot
    vals2, fig2, ax2 = extract_and_visualize(example, "other.*", plot_type="line")
    print("Extracted values from 'other.*':", vals2)
```

Notes:
- The function expects a Python object (dict/list) like what json.loads produces. If you have a JSON string use json.loads(json_string) before calling.
- Use "*" in the path to iterate over all elements in a list or all values in a dict at that level.
- Returns the numeric values array and the matplotlib figure/axis if you want further customization.

Here's a single self-contained Python function that extracts numeric values from a nested JSON-like structure (dicts/lists or a JSON string) following a specified path of keys, and visualizes them using matplotlib (a free library). The path can be provided as a dot-separated string (e.g. "items.*.value") or as a list of tokens. Use "*" as a wildcard to iterate over all elements of a list or all values of a dict.

Example usage is included in the docstring.

```python
def extract_and_visualize(json_data, path, plot_type='hist', bins=30,
                          figsize=(8, 5), title=None, xlabel=None, ylabel=None,
                          show=True, save_path=None):
    """
    Extract numeric values from a JSON-like structure and visualize them.

    - json_data: Python dict/list (parsed JSON) or a JSON string.
    - path: dot-separated string like "data.items.*.value" or a list of tokens.
            Use '*' to mean "for each element" (works with lists and dict values).
            Numeric indices as tokens (e.g. "0") will be interpreted for lists.
    - plot_type: 'hist' (histogram), 'line' (index vs value), or 'box' (boxplot).
    - bins: number of bins for histogram.
    - figsize: figure size tuple for matplotlib.
    - title, xlabel, ylabel: optional labels.
    - show: if True, calls plt.show().
    - save_path: if provided, saves the figure to this path (e.g., "out.png").

    Returns: (fig, ax, data_list) where data_list is the extracted numeric values.

    Raises ValueError if no numeric data is found.

    Example:
      data = {
          "measurements": [
              {"time": 1, "value": "10.5"},
              {"time": 2, "value": 12},
              {"time": 3, "value": "13.2"}
          ]
      }
      fig, ax, numbers = extract_and_visualize(data, "measurements.*.value", plot_type="line")
    """
    import json
    import math
    import numbers
    import matplotlib.pyplot as plt

    # Parse JSON string if necessary
    if isinstance(json_data, str):
        try:
            obj = json.loads(json_data)
        except Exception as e:
            raise ValueError(f"Invalid JSON string: {e}")
    else:
        obj = json_data

    # Normalize path to list of tokens
    if isinstance(path, str):
        tokens = [t for t in path.split('.') if t != '']
    elif isinstance(path, (list, tuple)):
        tokens = list(path)
    else:
        raise TypeError("path must be a dot-separated string or a list/tuple of tokens")

    # Helper to test and coerce numeric-like values
    def try_coerce_number(v):
        if isinstance(v, bool):
            return None  # treat booleans as non-numeric here
        if isinstance(v, numbers.Number):
            if math.isfinite(v):
                return float(v)
            return None
        if isinstance(v, str):
            try:
                f = float(v)
                if math.isfinite(f):
                    return f
            except Exception:
                return None
        return None

    # Recursive traversal following tokens, collecting numeric leaves
    collected = []

    def traverse(current, toks):
        if not toks:
            # We reached the end of the path: collect numeric values
            # If current is a list/dict, walk it recursively to find numeric leaves
            if isinstance(current, dict):
                for val in current.values():
                    traverse(val, [])
                return
            if isinstance(current, list):
                for item in current:
                    traverse(item, [])
                return
            # Try coercion
            num = try_coerce_number(current)
            if num is not None:
                collected.append(num)
            return

        token = toks[0]

        if token == '*':
            # Wildcard: iterate over all values in list or dict
            if isinstance(current, dict):
                for val in current.values():
                    traverse(val, toks[1:])
            elif isinstance(current, list):
                for item in current:
                    traverse(item, toks[1:])
            else:
                # nothing to iterate
                return
            return

        # Non-wildcard token:
        # If current is dict, use token as key
        if isinstance(current, dict):
            if token in current:
                traverse(current[token], toks[1:])
            else:
                # key missing: nothing to do
                return
            return

        # If current is list, try interpreting token as integer index
        if isinstance(current, list):
            try:
                idx = int(token)
            except Exception:
                # token is not an index: attempt to apply the token to all elements
                # e.g., path "items.value" where current is already a list -> apply next token to each
                for item in current:
                    traverse(item, toks)
                return
            # index-based access
            if -len(current) <= idx < len(current):
                traverse(current[idx], toks[1:])
            else:
                return
            return

        # If current is scalar and tokens remain, nothing to traverse
        return

    traverse(obj, tokens)

    if not collected:
        raise ValueError("No numeric data found at the specified path.")

    # Plotting
    fig, ax = plt.subplots(figsize=figsize)
    if plot_type == 'hist':
        ax.hist(collected, bins=bins)
        ax.set_ylabel(ylabel or "Count")
        ax.set_xlabel(xlabel or "Value")
    elif plot_type == 'line':
        ax.plot(range(len(collected)), collected, marker='o')
        ax.set_xlabel(xlabel or "Index")
        ax.set_ylabel(ylabel or "Value")
    elif plot_type == 'box':
        ax.boxplot(collected, vert=True)
        ax.set_ylabel(ylabel or "Value")
    else:
        raise ValueError("plot_type must be one of 'hist', 'line', or 'box'")

    if title:
        ax.set_title(title)

    plt.tight_layout()
    if save_path:
        fig.savefig(save_path)

    if show:
        plt.show()

    return fig, ax, collected
```

