```python
import json
import matplotlib.pyplot as plt
from typing import Any, List, Union

def extract_and_visualize_json(
    json_data: Union[str, dict],
    key_path: List[str],
    title: str = "JSON Data Visualization",
    chart_type: str = "line"
) -> None:
    """
    Extracts numerical data from a JSON structure and visualizes it.

    Args:
        json_data: JSON string or dictionary to extract data from
        key_path: List of keys representing the path to the data
                 (e.g., ["users", "stats", "scores"])
        title: Title for the visualization
        chart_type: Type of chart - "line", "bar", "scatter", or "hist"

    Returns:
        None (displays the plot)

    Raises:
        ValueError: If the data is not numerical or path is invalid
        TypeError: If json_data is not valid JSON or dict

    Example:
        >>> data = {
        ...     "company": {
        ...         "sales": [100, 200, 150, 300, 250]
        ...     }
        ... }
        >>> extract_and_visualize_json(data, ["company", "sales"], "Monthly Sales")
    """

    # Parse JSON if string is provided
    if isinstance(json_data, str):
        try:
            json_data = json.loads(json_data)
        except json.JSONDecodeError as e:
            raise TypeError(f"Invalid JSON string: {e}")

    if not isinstance(json_data, dict):
        raise TypeError("json_data must be a dictionary or valid JSON string")

    if not isinstance(key_path, list) or not key_path:
        raise ValueError("key_path must be a non-empty list of keys")

    # Navigate through the JSON structure using the key path
    current_data = json_data
    for key in key_path:
        if isinstance(current_data, dict) and key in current_data:
            current_data = current_data[key]
        else:
            raise ValueError(f"Key '{key}' not found in path {key_path}")

    # Validate that we have numerical data
    if isinstance(current_data, (list, tuple)):
        data = current_data
    else:
        data = [current_data]

    # Convert to numeric values
    try:
        numeric_data = [float(x) for x in data]
    except (ValueError, TypeError) as e:
        raise ValueError(f"Data contains non-numerical values: {e}")

    # Create visualization
    plt.figure(figsize=(10, 6))

    if chart_type == "line":
        plt.plot(numeric_data, marker='o', linewidth=2, markersize=8)
        plt.xlabel("Index")
        plt.ylabel("Value")

    elif chart_type == "bar":
        plt.bar(range(len(numeric_data)), numeric_data)
        plt.xlabel("Index")
        plt.ylabel("Value")

    elif chart_type == "scatter":
        plt.scatter(range(len(numeric_data)), numeric_data, s=100, alpha=0.6)
        plt.xlabel("Index")
        plt.ylabel("Value")

    elif chart_type == "hist":
        plt.hist(numeric_data, bins=10, edgecolor='black', alpha=0.7)
        plt.xlabel("Value")
        plt.ylabel("Frequency")

    else:
        raise ValueError(f"Unknown chart_type: {chart_type}. Use 'line', 'bar', 'scatter', or 'hist'")

    plt.title(title)
    plt.grid(True, alpha=0.3)
    plt.tight_layout()
    plt.show()


