import json
from typing import Optional, Tuple, List, Any
import math

import numpy as np
import matplotlib.pyplot as plt


def plot_normalized_json(
    json_str: str,
    key: Optional[str] = None,
    output_file: Optional[str] = None,
    show: bool = True,
    figsize: Tuple[int, int] = (8, 4),
    title: Optional[str] = None,
    xlabel: Optional[str] = None,
    ylabel: str = "Normalized",
) -> List[float]:
    """
    Parse a JSON string, extract a sequence of numeric values, Min-Max normalize them,
    plot them as a line chart, optionally save the plot, and return the normalized list.

    Behavior / accepted JSON shapes:
    - A JSON array of numbers: [1, 2, 3]
    - A JSON array of objects: [{"v": 1}, {"v": 2}, ...] — specify key='v' or it will attempt to auto-detect a single numeric key.
    - A JSON object whose values are numeric: {"a": 1, "b": 2, ...} — values are taken in insertion order (or key order for older Python versions).
    - A JSON object with a list value: {"series": [1,2,3]} — if any value is a list of numbers, that list will be used.
    - Mixed lists: numeric entries will be extracted in order; non-numeric entries are skipped unless you provide a key for objects.

    Parameters:
    - json_str: JSON string to parse.
    - key: optional key to extract from list-of-objects JSON.
    - output_file: if provided (e.g., 'plot.png'), the plot is saved to this file.
    - show: whether to call plt.show() to display the figure.
    - figsize: tuple for figure size in inches.
    - title, xlabel, ylabel: labels for the plot.

    Returns:
    - A Python list of floats: the Min-Max normalized values (range [0,1]). If all input values are identical,
      the normalized values will all be 0.0.

    Raises:
    - ValueError for unsupported JSON shapes or when no numeric data can be extracted.
    - json.JSONDecodeError if json_str is not valid JSON.
    """

    def is_number(x: Any) -> bool:
        # Exclude booleans (subclass of int)
        if isinstance(x, bool):
            return False
        if isinstance(x, (int, float)):
            return not (isinstance(x, float) and (math.isinf(x) or math.isnan(x)))
        # allow numeric strings like "3.14"
        if isinstance(x, str):
            try:
                float(x)
                return True
            except ValueError:
                return False
        return False

    def to_float(x: Any) -> float:
        if isinstance(x, bool):
            raise ValueError("boolean is not considered numeric here")
        return float(x)

    parsed = json.loads(json_str)

    values: List[float] = []

    # Case: list
    if isinstance(parsed, list):
        if all(is_number(item) for item in parsed):
            values = [to_float(item) for item in parsed]
        elif all(isinstance(item, dict) for item in parsed):
            # list of dicts
            if key is not None:
                extracted = []
                for i, d in enumerate(parsed):
                    v = d.get(key, None)
                    if v is None:
                        raise ValueError(f"Key '{key}' missing in element index {i}.")
                    if not is_number(v):
                        raise ValueError(f"Value for key '{key}' in element index {i} is not numeric.")
                    extracted.append(to_float(v))
                values = extracted
            else:
                # attempt to auto-detect single numeric key present in all dicts
                common_keys = set(parsed[0].keys())
                for d in parsed[1:]:
                    common_keys &= set(d.keys())
                numeric_keys = []
                for k in common_keys:
                    if all((k in d) and is_number(d[k]) for d in parsed):
                        numeric_keys.append(k)
                if len(numeric_keys) == 1:
                    values = [to_float(d[numeric_keys[0]]) for d in parsed]
                elif len(numeric_keys) > 1:
                    # choose the first but inform via ValueError for clarity
                    chosen = numeric_keys[0]
                    values = [to_float(d[chosen]) for d in parsed]
                else:
                    # fallback: collect any numeric entries in each dict in insertion order (flatten)
                    flat = []
                    for d in parsed:
                        numeric_found = False
                        for v in d.values():
                            if is_number(v):
                                flat.append(to_float(v))
                                numeric_found = True
                                break
                        if not numeric_found:
                            # skip dicts with no numeric value
                            pass
                    if flat:
                        values = flat
                    else:
                        raise ValueError("Could not auto-detect numeric field from list of objects; provide the 'key' parameter.")
        else:
            # mixed list: take numeric elements in order
            vals = []
            for i, item in enumerate(parsed):
                if is_number(item):
                    vals.append(to_float(item))
                elif isinstance(item, dict) and key is not None and key in item and is_number(item[key]):
                    vals.append(to_float(item[key]))
                # else skip
            if vals:
                values = vals
            else:
                raise ValueError("No numeric values found in the provided JSON list.")
    # Case: dict
    elif isinstance(parsed, dict):
        # if any value is a list of numeric, pick the first such list
        found_list = False
        for v in parsed.values():
            if isinstance(v, list) and v and all(is_number(x) for x in v):
                values = [to_float(x) for x in v]
                found_list = True
                break
        if not found_list:
            # if dict values themselves are numeric, use them in insertion order
            numeric_vals = [to_float(v) for v in parsed.values() if is_number(v)]
            if numeric_vals:
                values = numeric_vals
            else:
                raise ValueError("Dictionary JSON does not contain numeric values or list-of-numeric series.")
    # Single number
    elif is_number(parsed):
        values = [to_float(parsed)]
    else:
        raise ValueError("Unsupported JSON structure for numeric extraction.")

    if len(values) == 0:
        raise ValueError("No numeric data extracted from JSON.")

    arr = np.array(values, dtype=float)
    vmin = arr.min()
    vmax = arr.max()
    if vmax == vmin:
        norm = np.zeros_like(arr, dtype=float)
    else:
        norm = (arr - vmin) / (vmax - vmin)

    # Plot
    plt.figure(figsize=figsize)
    x = np.arange(len(norm))
    plt.plot(x, norm, marker='o', linestyle='-')
    plt.grid(True, linewidth=0.5, alpha=0.7)
    plt.xlabel(xlabel if xlabel is not None else "Index")
    plt.ylabel(ylabel)
    if title is not None:
        plt.title(title)
    else:
        plt.title("Min-Max Normalized Series")

    if output_file:
        plt.savefig(output_file, bbox_inches='tight')

    if show:
        plt.show()
    else:
        # if not showing, close to avoid display in some environments
        plt.close()

    return norm.tolist()


# Example usage:
if __name__ == "__main__":
    example_json = '[{"time": "2020-01-01", "value": 10}, {"time": "2020-01-02", "value": 20}, {"time": "2020-01-03", "value": 15}]'
    normalized = plot_normalized_json(example_json, key="value", title="Example", show=True)
    print("Normalized:", normalized)
