```python
"""
parse_html_table_to_sqlite(source, db_path, table_name, ...)

Parses an HTML table from a URL, a local file path, or a raw HTML string and stores
it into an SQLite database file.

Dependencies (free):
 - requests
 - beautifulsoup4

Install if needed:
 pip install requests beautifulsoup4

Example usage:
 parse_html_table_to_sqlite(
     source="https://example.com/page-with-table",
     db_path="mydata.db",
     table_name="my_table",
     css_selector="#main-table",
     if_exists="replace",
     convert_types=True,
     verbose=True
 )
"""

import re
import sqlite3
from typing import Optional, List, Tuple, Any

# External libs
try:
    import requests
    from bs4 import BeautifulSoup
except ImportError as e:
    raise ImportError(
        "Missing dependency. Please install required packages:\n"
        "pip install requests beautifulsoup4"
    ) from e


def parse_html_table_to_sqlite(
    source: str,
    db_path: str,
    table_name: str,
    *,
    table_index: int = 0,
    css_selector: Optional[str] = None,
    if_exists: str = "replace",  # 'replace' or 'append' or 'fail'
    header_rows: int = 1,
    convert_types: bool = True,
    timeout: int = 10,
    user_agent: Optional[str] = None,
    encoding: Optional[str] = None,
    verbose: bool = False,
) -> Tuple[int, List[Tuple[str, str]]]:
    """
    Parse an HTML table and store it into an SQLite database.

    Parameters
    - source: URL (http/https), local file path, or raw HTML string.
    - db_path: Path to SQLite database file. Will be created if it doesn't exist.
    - table_name: Name of the SQLite table to create/append to.
                  Must start with a letter or underscore and contain only letters, digits, underscores.
    - table_index: 0-based index of table to use when multiple tables are present and css_selector not provided.
    - css_selector: CSS selector to find the table (overrides table_index if provided).
    - if_exists: 'replace' (drop and recreate), 'append' (insert into existing), or 'fail' (raise if exists).
    - header_rows: number of header rows to consider (0 means auto-generated column names).
    - convert_types: try to convert values to INTEGER/REAL where appropriate.
    - timeout: requests timeout in seconds when fetching a URL.
    - user_agent: optional UA header for requests.
    - encoding: optional override for input HTML encoding (for local files / raw HTML decode).
    - verbose: print progress messages if True.

    Returns: (num_rows_inserted, list_of_columns_with_types)
    Example column: ("price", "REAL")

    Raises: ValueError on invalid inputs, ImportError for missing libs, requests errors for URL fetch failure.
    """

    # ---------- helpers ----------
    def _log(*args):
        if verbose:
            print(*args)

    def _is_url(s: str) -> bool:
        return s.startswith("http://") or s.startswith("https://")

    def _is_raw_html(s: str) -> bool:
        return "<table" in s.lower() or "<html" in s.lower()

    def _fetch_html(src: str) -> str:
        if _is_url(src):
            headers = {}
            if user_agent:
                headers["User-Agent"] = user_agent
            _log("Fetching URL:", src)
            resp = requests.get(src, timeout=timeout, headers=headers)
            resp.raise_for_status()
            if encoding:
                resp.encoding = encoding
            return resp.text
        # local file
        try:
            # If looks like raw HTML just return
            if _is_raw_html(src):
                _log("Using provided raw HTML string (not a file path).")
                return src
            _log("Reading local file:", src)
            with open(src, "rb") as f:
                raw = f.read()
                if encoding:
                    return raw.decode(encoding)
                # try to decode utf-8, fallback to latin-1
                try:
                    return raw.decode("utf-8")
                except UnicodeDecodeError:
                    return raw.decode("latin-1")
        except FileNotFoundError:
            raise ValueError(f"Source file not found: {src}")

    def _sanitize_db_identifier(name: str) -> str:
        # allow only [A-Za-z_][A-Za-z0-9_]*
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", name):
            return name
        raise ValueError(
            f"Invalid SQL identifier '{name}'. Only letters, digits and underscores allowed and must not start with a digit."
        )

    def _cell_text(cell) -> str:
        # get visible text, join with spaces for nested tags
        return cell.get_text(" ", strip=True)

    def _expand_colspan(cells):
        new = []
        for c in cells:
            colspan = 1
            try:
                colspan = int(c.get("colspan", 1))
            except Exception:
                colspan = 1
            text = _cell_text(c)
            for _ in range(colspan):
                new.append(text)
        return new

    def _try_parse_number(s: str) -> Optional[Any]:
        if s is None:
            return None
        t = s.strip()
        if t == "":
            return None
        # remove common currency and percent signs and parentheses-based negatives
        t2 = t.replace("\xa0", " ").strip()
        # handle "(123)" as negative
        is_neg_paren = False
        if t2.startswith("(") and t2.endswith(")"):
            is_neg_paren = True
            t2 = t2[1:-1].strip()
        # strip common currency/percent symbols
        t3 = re.sub(r"[$€£¥₹,]", "", t2)  # remove currency symbols and thousand separators (commas)
        t3 = t3.replace("%", "")
        # final trim
        t3 = t3.strip()
        if t3 == "":
            return None
        # attempt integer
        try:
            if re.fullmatch(r"[-+]?\d+", t3):
                val = int(t3)
                if is_neg_paren:
                    val = -val
                return val
            # float-like
            if re.fullmatch(r"[-+]?\d*\.\d+|\d+\.\d*", t3) or re.fullmatch(r"[-+]?\d+e[-+]?\d+", t3, flags=re.IGNORECASE):
                val = float(t3)
                if is_neg_paren:
                    val = -val
                return val
            # fallback: try to cast
            try:
                val = int(t3)
                if is_neg_paren:
                    val = -val
                return val
            except Exception:
                try:
                    val = float(t3)
                    if is_neg_paren:
                        val = -val
                    return val
                except Exception:
                    return None
        except Exception:
            return None

    # ---------- prepare ----------
    db_table = _sanitize_db_identifier(table_name)
    html = _fetch_html(source)

    soup = BeautifulSoup(html, "html.parser")
    # find table
    table = None
    if css_selector:
        _log("Using CSS selector:", css_selector)
        sel = soup.select(css_selector)
        if not sel:
            raise ValueError(f"No element found for selector: {css_selector}")
        # choose first matching table-like element
        # if user targeted a container, find first table inside it
        first = sel[table_index] if len(sel) > table_index else None
        if first is None:
            raise ValueError(f"No element at index {table_index} for selector {css_selector}")
        if first.name == "table":
            table = first
        else:
            table = first.find("table")
            if table is None:
                raise ValueError("Selector did not locate a <table> nor a container with a <table>.")
    else:
        tables = soup.find_all("table")
        if not tables:
            raise ValueError("No <table> elements found in source.")
        if table_index >= len(tables):
            raise ValueError(f"Requested table_index {table_index} but only {len(tables)} tables found.")
        table = tables[table_index]

    # parse rows
    rows = []
    header_cells_acc = []
    trs = table.find_all("tr")
    if not trs:
        raise ValueError("Selected <table> has no <tr> rows.")

    # Identify header rows: use th-containing rows first if header_rows>0, else use first n rows
    if header_rows > 0:
        header_count = 0
        for tr in trs:
            ths = tr.find_all(["th"])
            if ths:
                header_cells_acc.append(_expand_colspan(ths))
                header_count += 1
                if header_count >= header_rows:
                    break
        # if not enough th rows found, fall back to first rows (could have td used as header)
        if len(header_cells_acc) < header_rows:
            header_cells_acc = []
            for i, tr in enumerate(trs[:header_rows]):
                tds = tr.find_all(["th", "td"])
                header_cells_acc.append(_expand_colspan(tds))
    else:
        header_cells_acc = []

    # Data rows start after header_rows if we used fixed count, else after the last header-containing row
    data_start_index = 0
    if header_rows > 0:
        # find where the header rows came from among trs
        if any(tr.find_all("th") for tr in trs[:header_rows]):
            data_start_index = header_rows
        else:
            data_start_index = header_rows
    else:
        # try auto-detect: skip initial rows that contain only th
        idx = 0
        while idx < len(trs) and trs[idx].find_all("th"):
            idx += 1
        data_start_index = idx

    # Collect data row cells
    for tr in trs[data_start_index:]:
        # skip rows that only contain header-like THs if header_rows was 0 but initial rows had th
        cells = tr.find_all(["td", "th"])
        if not cells:
            continue
        expanded = _expand_colspan(cells)
        # convert to text
        row = [x.strip() if x is not None else "" for x in expanded]
        rows.append(row)

    # Build headers
    if header_cells_acc:
        # If multiple header rows, join them with " | " by column position
        max_len = max(len(h) for h in header_cells_acc)
        # normalize each header row to same length by padding
        for h in header_cells_acc:
            while len(h) < max_len:
                h.append("")
        combined = []
        for col_idx in range(max_len):
            parts = []
            for hr in header_cells_acc:
                txt = hr[col_idx].strip()
                if txt:
                    parts.append(txt)
            if parts:
                combined.append(" | ".join(parts))
            else:
                combined.append(f"col_{col_idx+1}")
        headers = combined
    else:
        # generate headers from the first data row length
        max_cols = 0
        if rows:
            max_cols = max(len(r) for r in rows)
        headers = [f"col_{i+1}" for i in range(max_cols)]

    # normalize data rows to header length
    ncols = len(headers)
    normalized_rows = []
    for r in rows:
        if len(r) < ncols:
            nr = r + [None] * (ncols - len(r))
        else:
            nr = r[:ncols]
        normalized_rows.append(nr)

    # Clean whitespace and empty strings -> None
    cleaned_rows = []
    for r in normalized_rows:
        cleaned = []
        for v in r:
            if v is None:
                cleaned.append(None)
            else:
                t = v.strip()
                if t == "":
                    cleaned.append(None)
                else:
                    cleaned.append(t)
        cleaned_rows.append(cleaned)

    # Type inference per column
    col_types = ["TEXT"] * ncols
    if convert_types:
        inferred = []
        for ci in range(ncols):
            col_vals = [cleaned_rows[r][ci] for r in range(len(cleaned_rows)) if cleaned_rows[r][ci] is not None]
            parsed_types = []
            for val in col_vals:
                num = _try_parse_number(val)
                if num is None:
                    parsed_types.append("TEXT")
                elif isinstance(num, int):
                    parsed_types.append("INTEGER")
                else:
                    parsed_types.append("REAL")
            # decide column type
            if not parsed_types:
                col_types[ci] = "TEXT"
            else:
                # if all INTEGER -> INTEGER; else if only INTEGER or REAL -> REAL; else TEXT
                uniq = set(parsed_types)
                if uniq == {"INTEGER"}:
                    col_types[ci] = "INTEGER"
                elif uniq <= {"INTEGER", "REAL"}:
                    col_types[ci] = "REAL"
                else:
                    col_types[ci] = "TEXT"
    else:
        col_types = ["TEXT"] * ncols

    # Prepare sanitized column names
    def _sanitize_col_name(name: str, idx: int) -> str:
        # replace spaces and illegal chars with underscore, ensure starts with letter or underscore
        n = name.strip()
        n = re.sub(r"\s+", "_", n)
        n = re.sub(r"[^\w]", "_", n)
        if not re.match(r"^[A-Za-z_]", n):
            n = f"c{idx+1}_{n}"
        # ensure not empty
        if n == "":
            n = f"col_{idx+1}"
        return n

    col_names = []
    seen = {}
    for i, h in enumerate(headers):
        candidate = _sanitize_col_name(h, i)
        # avoid duplicates
        if candidate in seen:
            seen[candidate] += 1
            candidate = f"{candidate}_{seen[candidate]}"
        else:
            seen[candidate] = 1
        col_names.append(candidate)

    _log("Columns:", list(zip(col_names, col_types)))
    # Convert cleaned_rows values to appropriate Python types for insertion
    prepared_rows = []
    for r in cleaned_rows:
        newr = []
        for ci, v in enumerate(r):
            if v is None:
                newr.append(None)
            elif convert_types and col_types[ci] in ("INTEGER", "REAL"):
                num = _try_parse_number(v)
                # If number parsing fails, keep original string
                if num is None:
                    newr.append(v)
                else:
                    newr.append(num)
            else:
                newr.append(v)
        prepared_rows.append(tuple(newr))

    # ---------- store into SQLite ----------
    conn = sqlite3.connect(db_path)
    try:
        cur = conn.cursor()
        # check existing table
        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (db_table,))
        exists = cur.fetchone() is not None
        if exists:
            if if_exists == "fail":
                raise ValueError(f"Table '{db_table}' already exists in {db_path}.")
            elif if_exists == "replace":
                _log("Dropping existing table", db_table)
                cur.execute(f'DROP TABLE IF EXISTS "{db_table}"')
                conn.commit()
            elif if_exists == "append":
                # try to verify schema compatibility minimally: check column count
                cur.execute(f'PRAGMA table_info("{db_table}")')
                existing_infos = cur.fetchall()  # cid, name, type, notnull, dflt_value, pk
                if existing_infos and len(existing_infos) != len(col_names):
                    raise ValueError(
                        f"Existing table '{db_table}' has {len(existing_infos)} columns but parsed table has {len(col_names)}."
                    )
                # else we proceed to insert
            else:
                raise ValueError("if_exists must be one of 'replace', 'append', 'fail'")

        # create table if needed
        if not exists or if_exists == "replace":
            cols_def = ", ".join(f'"{cn}" {ct}' for cn, ct in zip(col_names, col_types))
            create_sql = f'CREATE TABLE "{db_table}" ({cols_def})'
            _log("Creating table with SQL:", create_sql)
            cur.execute(create_sql)
            conn.commit()

        # Insert rows
        if prepared_rows:
            placeholders = ", ".join(["?"] * len(col_names))
            insert_sql = f'INSERT INTO "{db_table}" ({", ".join(f\'"{c}"\' for c in col_names)}) VALUES ({placeholders})'
            _log("Inserting rows (SQL):", insert_sql)
            cur.executemany(insert_sql, prepared_rows)
            conn.commit()
            num_inserted = cur.rowcount if cur.rowcount != -1 else len(prepared_rows)
        else:
            num_inserted = 0

        # return list of (col_name, col_type)
        result_types = list(zip(col_names, col_types))
        _log(f"Inserted {num_inserted} rows into {db_path}.{db_table}")
        return num_inserted, result_types
    finally:
        conn.close()


# If this module is run directly, a short demo (requires internet access):
