from typing import Optional, Tuple
from PIL import Image, ExifTags
import pytesseract
import chardet
import unicodedata

def extract_text_from_image(path: str, lang: str = 'eng') -> str:
    """
    Open an image file, run OCR to extract text, normalize/convert encodings,
    and if OCR yields nothing useful, fall back to decoding image comment / EXIF text.

    Returns a Unicode string (decoded to Python str). Returns empty string on failure/no text.

    Dependencies:
      - pillow
      - pytesseract (requires Tesseract binary installed)
      - chardet
    """
    def safe_decode_bytes(b: bytes) -> str:
        # Try to handle EXIF UserComment special prefixes
        if not b:
            return ''
        # If EXIF UserComment prefix present, handle common tags
        prefix_ascii = b'ASCII\0\0\0'
        prefix_unicode = b'UNICODE\0'
        prefix_jis = b'JIS\0\0\0\0'
        if b.startswith(prefix_ascii):
            try:
                return b[len(prefix_ascii):].decode('ascii', errors='replace')
            except Exception:
                pass
        if b.startswith(prefix_unicode):
            try:
                # Usually indicates UTF-16
                return b[len(prefix_unicode):].decode('utf-16', errors='replace')
            except Exception:
                pass
        if b.startswith(prefix_jis):
            try:
                return b[len(prefix_jis):].decode('shift_jis', errors='replace')
            except Exception:
                pass

        # Generic detection
        try:
            guess = chardet.detect(b)
            enc = guess.get('encoding')
            if enc:
                return b.decode(enc, errors='replace')
        except Exception:
            pass

        # fallback attempts
        for enc in ('utf-8', 'utf-16', 'utf-16le', 'latin-1', 'cp1252'):
            try:
                return b.decode(enc, errors='replace')
            except Exception:
                continue
        # Last resort: bytes -> str via latin-1
        return b.decode('latin-1', errors='replace')

    def extract_exif_comments(img: Image.Image) -> Optional[str]:
        # Check Image.info for PNG tEXt or JPEG comment
        info = getattr(img, 'info', {}) or {}
        # common keys: 'comment', 'Comment', 'description', 'Description'
        candidate_keys = ['comment', 'Comment', 'description', 'Description']
        parts = []
        for k in candidate_keys:
            if k in info:
                v = info[k]
                if isinstance(v, bytes):
                    parts.append(safe_decode_bytes(v))
                elif isinstance(v, str):
                    parts.append(v)
        # Try EXIF tags
        try:
            exif = img.getexif()
        except Exception:
            exif = None

        if exif:
            # map numeric tags to names
            tag_map = {v: k for k, v in ExifTags.TAGS.items()}
            # look for common text tags
            text_tags = ('ImageDescription', 'UserComment', 'XPComment', 'XPTitle', 'XPAuthor', 'XPKeywords')
            for tname in text_tags:
                # find tag id if present
                tag_id = None
                for tid, name in ExifTags.TAGS.items():
                    if name == tname:
                        tag_id = tid
                        break
                if tag_id is None:
                    continue
                if tag_id in exif:
                    val = exif[tag_id]
                    if isinstance(val, bytes):
                        parts.append(safe_decode_bytes(val))
                    elif isinstance(val, (tuple, list)):
                        # XP* tags often returned as byte-value tuples for UTF-16LE
                        try:
                            b = bytes(val)
                            # XP tags usually UTF-16LE
                            try:
                                parts.append(b.decode('utf-16le').rstrip('\x00'))
                            except Exception:
                                parts.append(safe_decode_bytes(b))
                        except Exception:
                            # fallback to join components
                            try:
                                parts.append(''.join(map(str, val)))
                            except Exception:
                                pass
                    elif isinstance(val, str):
                        parts.append(val)
                    else:
                        # last resort: str()
                        parts.append(str(val))
        if parts:
            # join with newlines and normalize
            joined = '\n'.join(p for p in parts if p)
            return unicodedata.normalize('NFC', joined)
        return None

    # Main logic
    try:
        with Image.open(path) as img:
            # Attempt OCR first
            try:
                ocr_text = pytesseract.image_to_string(img, lang=lang)
            except Exception:
                ocr_text = ''
            if ocr_text:
                ocr_text_stripped = ocr_text.strip()
            else:
                ocr_text_stripped = ''

            if ocr_text_stripped:
                # Normalize and return
                return unicodedata.normalize('NFC', ocr_text_stripped)

            # Fallback: try to extract comments/EXIF text
            comment_text = extract_exif_comments(img)
            if comment_text:
                return comment_text

            # No text found
            return ''
    except Exception:
        return ''
