Notes:
- Requires Pillow and pytesseract Python packages: pip install pillow pytesseract
- pytesseract is a wrapper for the Tesseract OCR engine; you must also install the Tesseract binary on your system (e.g., apt install tesseract-ocr on Debian/Ubuntu or use the appropriate installer for Windows/macOS).
- chardet is optional but recommended for better encoding detection: pip install chardet

Code:

```python
from typing import Tuple, Optional
from PIL import Image, ExifTags
import io

# Optional imports
try:
    import pytesseract
    from pytesseract import TesseractError, TesseractNotFoundError
except Exception:
    pytesseract = None
    TesseractError = Exception
    TesseractNotFoundError = Exception

try:
    import chardet
except Exception:
    chardet = None


def extract_text_from_image(
    image_path: str,
    ocr_lang: str = 'eng',
    ocr_config: Optional[str] = None,
    prefer_ocr: bool = True,
    return_bytes: bool = False,
    output_encoding: str = 'utf-8'
) -> Tuple[Optional[bytes], Optional[str]]:
    """
    Open image at image_path, attempt OCR to extract text. If OCR fails or returns
    empty text, fall back to reading image comment / EXIF UserComment metadata.
    Returns a tuple (text, source) where:
      - text is a Python str (Unicode) by default, or bytes if return_bytes=True (encoded
        using output_encoding).
      - source is 'ocr', 'comment', or None if no text found.

    Parameters:
      image_path: path to the image file.
      ocr_lang: language code passed to pytesseract (default 'eng').
      ocr_config: additional config string for pytesseract (e.g., "--psm 3").
      prefer_ocr: if True, try OCR first and only fall back to metadata if OCR empty.
                  If False, check metadata first then OCR.
      return_bytes: if True, return bytes encoded using output_encoding; else return str.
      output_encoding: encoding to use when return_bytes=True (default 'utf-8').

    Requires:
      - Pillow (PIL)
      - pytesseract and the Tesseract binary for OCR (optional if you only need metadata)
      - chardet (optional, to better detect encodings of metadata)
    """

    def _normalize_text(s: Optional[str]) -> Optional[str]:
        if s is None:
            return None
        s2 = s.strip()
        return s2 if s2 != '' else None

    def _detect_and_decode(b: bytes) -> str:
        # Some Exif UserComment values have a prefix indicating charset, e.g.:
        # b'ASCII\x00\x00\x00Hello...' or b'UNICODE\x00...' etc.
        if not b:
            return ''
        # Try common EXIF user comment headers:
        if b.startswith(b'ASCII\x00\x00\x00'):
            try:
                return b[8:].decode('ascii', errors='replace')
            except Exception:
                pass
        if b.startswith(b'UNICODE\x00') or b.startswith(b'UNICODE\0'):
            # Often unicode comments are UTF-16
            try:
                return b[8:].decode('utf-16', errors='replace')
            except Exception:
                pass
        if b.startswith(b'JIS\x00\x00\x00'):
            # Fallback attempt for JIS (rare)
            try:
                return b[8:].decode('shift_jis', errors='replace')
            except Exception:
                pass

        # If chardet available, use it
        if chardet is not None:
            try:
                guess = chardet.detect(b)
                enc = guess.get('encoding')
                if enc:
                    return b.decode(enc, errors='replace')
            except Exception:
                pass

        # Fallback try a few encodings
        for enc in ('utf-8', 'utf-16', 'latin-1', 'cp1252'):
            try:
                return b.decode(enc, errors='replace')
            except Exception:
                continue
        # Last resort: latin-1 with replacement
        return b.decode('latin-1', errors='replace')

    def _extract_comment_from_image(img: Image.Image) -> Optional[str]:
        # 1) PNG/text chunks and other info keys
        info = getattr(img, 'info', {}) or {}
        text_candidates = []
        for k, v in info.items():
            # Some values may be bytes, some strings
            if isinstance(v, bytes):
                text_candidates.append(_detect_and_decode(v))
            elif isinstance(v, str):
                text_candidates.append(v)
            # Sometimes Pillow stores multiple text entries under 'text' dict
            elif isinstance(v, dict):
                for kk, vv in v.items():
                    if isinstance(vv, bytes):
                        text_candidates.append(_detect_and_decode(vv))
                    elif isinstance(vv, str):
                        text_candidates.append(vv)

        # 2) EXIF user comment (JPEG/other)
        try:
            exif = img.getexif()
            if exif:
                # 37510 is the EXIF tag for UserComment
                USER_COMMENT_TAG = 37510
                if USER_COMMENT_TAG in exif:
                    uc = exif[USER_COMMENT_TAG]
                    if isinstance(uc, bytes):
                        text_candidates.append(_detect_and_decode(uc))
                    elif isinstance(uc, str):
                        text_candidates.append(uc)
        except Exception:
            # Some image types might not support getexif or may raise
            pass

        # Join non-empty candidates (preserve reasonable spacing/newlines)
        filtered = [c.strip() for c in text_candidates if c and c.strip()]
        if not filtered:
            return None
        # If multiple candidates, join with double newline to separate blocks
        return "\n\n".join(filtered)

    # Main workflow
    img = Image.open(image_path)

    def do_ocr(image: Image.Image) -> Optional[str]:
        if pytesseract is None:
            return None
        try:
            cfg = ocr_config if ocr_config is not None else ''
            text = pytesseract.image_to_string(image, lang=ocr_lang, config=cfg)
            return _normalize_text(text)
        except TesseractNotFoundError:
            # Tesseract binary not found on system
            return None
        except Exception:
            # Any other OCR failure
            return None

    text_result = None
    source = None

    if prefer_ocr:
        text_result = do_ocr(img)
        if text_result:
            source = 'ocr'
        else:
            # Fallback to metadata
            meta = _extract_comment_from_image(img)
            meta = _normalize_text(meta)
            if meta:
                text_result = meta
                source = 'comment'
    else:
        # Try metadata first
        meta = _extract_comment_from_image(img)
        meta = _normalize_text(meta)
        if meta:
            text_result = meta
            source = 'comment'
        else:
            text_result = do_ocr(img)
            if text_result:
                source = 'ocr'

    if not text_result:
        return (None, None)

    # Return bytes if requested
    if return_bytes:
        return (text_result.encode(output_encoding, errors='replace'), source)
    return (text_result, source)
```

