Below is a single self-contained Python function (with necessary imports) that opens an image file, tries to extract text using OCR (pytesseract), attempts to fix encoding issues (using chardet), and if OCR yields nothing falls back to reading image comments/metadata (EXIF / PNG text). It returns a Unicode Python string (decoded to the requested target encoding).

Prerequisites:
- Install Python packages: pip install pillow pytesseract chardet
- Install Tesseract OCR engine separately (must be in PATH). If it's in a custom location, pass tesseract_cmd to the function.

Function:

```python
from typing import Optional
from PIL import Image, ExifTags
import pytesseract
import chardet

def extract_text_from_image(
    image_path: str,
    target_encoding: str = 'utf-8',
    ocr_lang: str = 'eng',
    ocr_config: str = '--psm 3',
    tesseract_cmd: Optional[str] = None
) -> str:
    """
    Open an image, extract text via OCR, convert/refine encoding, and if OCR yields
    nothing fall back to extracting image comment/metadata.

    Args:
        image_path: Path to the image file.
        target_encoding: Desired encoding name for the returned text (function returns
                         a Python str; this controls detection/decoding behavior).
        ocr_lang: Tesseract language(s) (e.g. 'eng', 'eng+fra').
        ocr_config: Extra tesseract config (e.g. '--psm 3').
        tesseract_cmd: If Tesseract binary is not in PATH, set pytesseract.pytesseract.tesseract_cmd.

    Returns:
        Extracted text as a Python str (Unicode). Empty string if nothing found.
    """
    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    def _try_fix_encoding(s: str) -> str:
        # Try to detect if the Unicode string was decoded with a wrong encoding
        # by re-encoding with latin-1 to recover original bytes and using chardet.
        if not s:
            return ''
        s = s.strip('\x00')  # remove nulls commonly present in some metadata
        # Quick pass: if string is all ASCII, return it
        if all(ord(ch) < 128 for ch in s):
            return s
        try:
            raw_bytes = s.encode('latin-1', errors='ignore')
            detected = chardet.detect(raw_bytes)
            enc = detected.get('encoding')
            if enc:
                try:
                    decoded = raw_bytes.decode(enc, errors='replace')
                    return decoded
                except Exception:
                    pass
        except Exception:
            pass
        # as last resort return original string
        return s

    def _extract_comment_from_info(info_dict) -> Optional[str]:
        # Common keys for embedded text in PIL info dict
        keys = ['comment', 'Comment', 'description', 'Description', 'UserComment', 'Text']
        for k in keys:
            if k in info_dict and info_dict[k]:
                v = info_dict[k]
                if isinstance(v, bytes):
                    detected = chardet.detect(v)
                    enc = detected.get('encoding') or target_encoding
                    try:
                        return v.decode(enc, errors='replace')
                    except Exception:
                        return v.decode('utf-8', errors='replace')
                else:
                    return str(v)
        return None

    def _extract_from_exif(img: Image.Image) -> Optional[str]:
        # Try to read EXIF tags that commonly contain comments
        exif = None
        try:
            # Pillow 6+: use getexif(); older versions use _getexif()
            if hasattr(img, "getexif"):
                exif = img.getexif()
            elif hasattr(img, "_getexif"):
                exif = img._getexif()
        except Exception:
            exif = None

        if not exif:
            return None

        # exif might be a dict-like mapping of tag->value
        for tag, val in dict(exif).items():
            name = ExifTags.TAGS.get(tag, tag)
            if name in ('UserComment', 'ImageDescription', 'XPComment', 'XPTitle', 'XPSubject'):
                if isinstance(val, bytes):
                    det = chardet.detect(val)
                    enc = det.get('encoding') or target_encoding
                    try:
                        return val.decode(enc, errors='replace')
                    except Exception:
                        return val.decode('utf-8', errors='replace')
                # XP* tags sometimes come as byte arrays or lists of ints (UTF-16LE)
                if isinstance(val, (list, tuple)) and all(isinstance(i, int) for i in val):
                    try:
                        b = bytes(i & 0xFF for i in val)
                        return b.decode('utf-16le', errors='replace')
                    except Exception:
                        return str(val)
                return str(val)
        return None

    # Open image and attempt OCR first
    try:
        with Image.open(image_path) as img:
            # OCR attempt
            try:
                raw_ocr = pytesseract.image_to_string(img, lang=ocr_lang, config=ocr_config)
                raw_ocr = raw_ocr.strip()
                if raw_ocr:
                    return _try_fix_encoding(raw_ocr)
            except Exception:
                # If OCR fails, continue to fallback
                pass

            # Fallback #1: image.info dictionary (PNG tEXt, GIF comment, etc.)
            try:
                info_text = _extract_comment_from_info(img.info or {})
                if info_text and info_text.strip():
                    return _try_fix_encoding(info_text)
            except Exception:
                pass

            # Fallback #2: EXIF metadata (JPEG and others)
            try:
                exif_text = _extract_from_exif(img)
                if exif_text and exif_text.strip():
                    return _try_fix_encoding(exif_text)
            except Exception:
                pass

    except Exception:
        # Could not open image or other fatal error
        return ''

    # Nothing found
    return ''
