                    elif ch in ('"', "'"):
                        # skip string content to avoid braces inside strings
                        quote = ch
                        i3 = i2 + 1
                        while i3 < L:
                            if s[i3] == '\\':
                                i3 += 2
                            elif s[i3] == quote:
                                i2 = i3
                                break
                            else:
                                i3 += 1
                    i2 += 1
                else:
                    # no matching closing brace
                    i += 1
            else:
                i += 1
        return objs

    def normalize_js_object(s: str) -> str:
        # Try to make JS-like object more JSON-friendly:
        s = remove_js_comments(s)

        # Remove trailing commas like {...,} or [...,]
        s = re.sub(r',\s*(?=[}\]])', '', s)

        # Replace single-quoted strings with double-quoted strings (approx)
        s = re.sub(r"'([^'\\]*(?:\\.[^'\\]*)*)'", r'"\1"', s)

        # Quote unquoted keys: { key: ... }  ->  { "key": ... }
        # This is a heuristic and may not cover all edge cases.
        def _quote_keys(match):
            lead = match.group(1)
            key = match.group(2)
            return f'{lead}"{key}":'
        s = re.sub(r'([{\s,])([A-Za-z_][A-Za-z0-9_-]*)\s*:', _quote_keys, s)

        return s

    def try_parse(s: str):
        # Try a bunch of parsers/strategies; return Python object or raise.
        # Strategy 1: strict JSON
        try:
            return json.loads(s)
        except Exception:
            pass

        # Strategy 2: json5 (if available)
        if json5 is not None:
            try:
                return json5.loads(s)
            except Exception:
                pass

        # Strategy 3: demjson (if available)
        if demjson is not None:
            try:
                return demjson.decode(s)
            except Exception:
                pass

        # Strategy 4: normalize and try json.loads again
        norm = normalize_js_object(s)
        try:
            return json.loads(norm)
        except Exception:
            pass

        # Strategy 5: Try ast.literal_eval (safe, Python literal syntax)
        try:
            return ast.literal_eval(s)
        except Exception:
            pass

        # Give up
        raise ValueError("Could not parse as dict-like structure")

