def fetch_and_extract_dicts(url, timeout=10):
    """
    Fetch the webpage at `url`, parse <script> tags, and attempt to extract any
    JSON-like objects contained in those scripts as Python dicts.

    Returns a list of unique dicts found (order preserved).

    Dependencies: requests, beautifulsoup4 (bs4). Install with:
      pip install requests beautifulsoup4

    Example:
      dicts = fetch_and_extract_dicts("https://example.com")
    """
    import re
    import json
    import ast
    import requests
    from bs4 import BeautifulSoup

    def find_brace_objects(text):
        """Yield substrings that start with '{' and end at the matching '}', handling strings/escapes."""
        length = len(text)
        i = 0
        while i < length:
            if text[i] != '{':
                i += 1
                continue
            depth = 0
            in_str = False
            str_char = None
            esc = False
            j = i
            while j < length:
                c = text[j]
                if in_str:
                    if esc:
                        esc = False
                    elif c == '\\':
                        esc = True
                    elif c == str_char:
                        in_str = False
                        str_char = None
                else:
                    if c == '"' or c == "'":
                        in_str = True
                        str_char = c
                    elif c == '{':
                        depth += 1
                    elif c == '}':
                        depth -= 1
                        if depth == 0:
                            yield text[i:j+1]
                            break
                j += 1
            i += 1

    headers = {'User-Agent': 'python-requests/1.0 (+https://example.org)'}
    resp = requests.get(url, headers=headers, timeout=timeout)
    resp.raise_for_status()
    soup = BeautifulSoup(resp.text, 'html.parser')
    scripts = soup.find_all('script')

    found_dicts = []
    for script in scripts:
        content = script.string if script.string is not None else script.get_text()
        if not content:
            continue
        content = content.strip()
        if not content:
            continue

        # 1) Try parsing the whole script as JSON
        try:
            obj = json.loads(content)
            if isinstance(obj, dict):
                found_dicts.append(obj)
            elif isinstance(obj, list):
                # optionally accept lists that contain dicts: extend with dict members
                for item in obj:
                    if isinstance(item, dict):
                        found_dicts.append(item)
        except Exception:
            pass

        # 2) Find JSON-like {...} substrings and try to parse them
        for candidate in find_brace_objects(content):
            # First try strict JSON
            try:
                obj = json.loads(candidate)
                if isinstance(obj, dict):
                    found_dicts.append(obj)
                elif isinstance(obj, list):
                    for item in obj:
                        if isinstance(item, dict):
                            found_dicts.append(item)
                continue
            except Exception:
                pass

            # Fallback: convert JS literals to Python and try ast.literal_eval (safer than eval)
            # Replace true/false/null with Python equivalents (word boundaries)
            candidate_py = re.sub(r'\btrue\b', 'True', candidate, flags=re.IGNORECASE)
            candidate_py = re.sub(r'\bfalse\b', 'False', candidate_py, flags=re.IGNORECASE)
            candidate_py = re.sub(r'\bnull\b', 'None', candidate_py, flags=re.IGNORECASE)
            try:
                obj = ast.literal_eval(candidate_py)
                if isinstance(obj, dict):
                    found_dicts.append(obj)
                elif isinstance(obj, list):
                    for item in obj:
                        if isinstance(item, dict):
                            found_dicts.append(item)
            except Exception:
                # Could not parse this candidate; skip
                pass

    # Deduplicate (by JSON canonicalization) while preserving order
    unique = []
    seen = set()
    for d in found_dicts:
        try:
            key = json.dumps(d, sort_keys=True, default=str)
        except Exception:
            # Fallback for non-JSON-serializable values
            key = repr(d)
        if key not in seen:
            seen.add(key)
            unique.append(d)
    return unique

