import re
import requests
import tldextract

def get_geolocation_data(ip):
    url = f"http://ip-api.com/json/{ip}"
    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        return None

def extract_urls(text):
    url_pattern = re.compile(r'https?://\S+')
    return url_pattern.findall(text)

def extract_domain(url):
    return tldextract.extract(url).domain

def get_domain_geolocation(url):
    try:
        domain = extract_domain(url)
        ip = requests.get(f"http://ip-api.com/json/{domain}").json().get('query')
        if ip:
            return get_geolocation_data(ip)
        else:
            return None
    except Exception as e:
        print(f"Error processing URL {url}: {e}")
        return None

def analyze_urls(text):
    urls = extract_urls(text)
    results = {}
    for url in urls:
        geolocation_data = get_domain_geolocation(url)
        if geolocation_data:
            results[url] = geolocation_data
    return results

